window.GUIDE_DATA={"revision":"2026-10-22 · 14","releaseUrl":"https://github.com/1363306384/streamplay-studio/releases","siteUrl":"https://1363306384.github.io/tiktok/streamplay-guide/","order":["home","download","account","start","cast","camera","modes","gifts","live","sticker","group","one","solo","multi","scene","finish","help"],"nav":[["overview",["home"]],["setup",["download","account","start","cast","camera","modes","gifts","live"]],["games",["sticker","group","one","solo","multi"]],["reference",["scene","finish","help"]]],"pages":{"start":{"title":{"en":"Workspace overview","zh":"软件概览"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">THE WORKSPACE</div><h1>Workspace overview</h1><p class=\"lead\">Get to know the main areas in Studio. Then use the contents to set up members, video and games.</p></div><h2>Get to know the workspace</h2><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/home.png\" data-caption=\"Studio workspace: scenes and games on the left, preview in the middle, LIVE Chat on the right\" aria-label=\"Enlarge: Studio workspace: scenes and games on the left, preview in the middle, LIVE Chat on the right\"><img src=\"assets/home.png\" alt=\"Studio workspace: scenes and games on the left, preview in the middle, LIVE Chat on the right\" loading=\"lazy\"></button><figcaption><span>Studio workspace: scenes and games on the left, preview in the middle, LIVE Chat on the right</span><span></span></figcaption></figure><table class=\"simple-table\"><tbody><tr><td>Account menu</td><td>Manage Cast members and switch accounts.</td></tr><tr><td>Scene</td><td>Configure the camera, rankings, wheel and other overlays.</td></tr><tr><td>Modes</td><td>Choose and configure an interactive game.</td></tr><tr><td>Center preview</td><td>Check the camera feed. Add the separate game overlay to OBS.</td></tr><tr><td>LIVE Chat</td><td>Read chat and LIVE statistics after connecting.</td></tr></tbody></table><div class=\"note\">There are three separate starts: your streaming software goes live; the top Start button connects LIVE data; Play and Start round start a game.</div>","zh":"<div class=\"hero\"><div class=\"eyebrow\">软件界面</div><h1>软件概览</h1><p class=\"lead\">先认识 Studio 的主要区域，之后按左侧目录完成成员、画面和玩法设置。</p></div><h2>先认清这几个位置</h2><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/home.png\" data-caption=\"Studio 首页：左边配置场景与玩法，中间预览，右边查看直播互动\" aria-label=\"放大：Studio 首页：左边配置场景与玩法，中间预览，右边查看直播互动\"><img src=\"assets/home.png\" alt=\"Studio 首页：左边配置场景与玩法，中间预览，右边查看直播互动\" loading=\"lazy\"></button><figcaption><span>Studio 首页：左边配置场景与玩法，中间预览，右边查看直播互动</span><span></span></figcaption></figure><table class=\"simple-table\"><thead><tr><th>位置</th><th>用来做什么</th></tr></thead><tbody><tr><td>右上角账号</td><td>管理 Cast 成员、切换账号。</td></tr><tr><td>Scene</td><td>设置摄像头、排行榜、转盘等画面组件。</td></tr><tr><td>Modes</td><td>选择并设置游戏玩法。</td></tr><tr><td>中间画面</td><td>检查摄像头预览。互动叠加层还需接入 OBS。</td></tr><tr><td>LIVE Chat</td><td>查看连接后的聊天与直播数据。</td></tr></tbody></table><div class=\"note\"><strong>记住三个开始：</strong>直播软件负责开播；顶部 Start 连接直播数据；模式里的 Play / Start round 开始游戏。</div>"}},"download":{"title":{"en":"Download and install","zh":"下载与安装"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">BEFORE YOU START</div><h1>Download and install</h1><p class=\"lead\">Install the desktop app, then sign in with your Studio account.</p></div><ol class=\"steps\"><li><h3>Choose the latest stable release</h3><p><a href=\"https://github.com/1363306384/streamplay-studio/releases\" target=\"_blank\" rel=\"noopener\">Open the official download page ↗</a>, find the release marked Latest and expand Assets.</p></li><li><h3>Choose the installer for your computer</h3><p>For Windows 64-bit, choose the x64 .exe installer. For an Apple Silicon Mac, choose the Apple Silicon / arm64 .dmg. Source code, .yml and .blockmap files are not installers.</p></li><li><h3>Install and open Studio</h3><p>On Windows, run the installer and follow its prompts. On Mac, open the DMG, drag the app into Applications, then open it from there.</p></li></ol><div class=\"note\">Release notes list Windows x64 and Apple Silicon Mac installers. For an Intel Mac, check for a compatible installer. Use the files currently offered on the download page.</div><p class=\"completion-check\"><span>Check before continuing: </span>Studio opens normally and shows the sign-in screen or your signed-in workspace.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">BEFORE YOU START</div><h1>下载与安装</h1><p class=\"lead\">先安装桌面版，再登录 Studio 账号。</p></div><ol class=\"steps\"><li><h3>选择最新稳定版本</h3><p><a href=\"https://github.com/1363306384/streamplay-studio/releases\" target=\"_blank\" rel=\"noopener\">打开官方下载页 ↗</a>，找到标记 Latest 的版本，展开 Assets。</p></li><li><h3>下载对应安装包</h3><p>Windows 64 位选择 x64 的 .exe 安装包；Apple Silicon Mac 选择 Apple Silicon / arm64 的 .dmg。不要下载 Source code、.yml 或 .blockmap。</p></li><li><h3>安装后打开 Studio</h3><p>Windows 双击安装程序，按提示完成。Mac 打开 DMG，将应用拖入“应用程序”，再从那里打开。</p></li></ol><div class=\"note\">发布说明提供 Windows x64 与 Apple Silicon Mac 安装包。Intel Mac 用户请先确认 Releases 是否已有兼容包。以下载页当前提供的文件为准。</div><p class=\"completion-check\"><span>完成后检查：</span>能正常打开 Streamplay Studio，并看到登录页或已登录的首页。</p>"}},"account":{"title":{"en":"Sign in and switch accounts","zh":"登录与切换账号"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">ACCOUNT</div><h1>Sign in and switch accounts</h1><p class=\"lead\">Sign in to Studio, then confirm that the top-right account is the one you will use for this LIVE.</p></div><h2>Sign in for the first time</h2><ol class=\"steps\"><li><h3>Open the sign-in screen</h3><p>Launch Studio. Enter your Studio account in ID and your password in Password, then click Sign In.</p></li><li><h3>Check the active account</h3><p>On the home screen, open the top-right account menu and check Active Profile. Signing in to Studio and connecting TikTok LIVE are separate steps.</p></li></ol><h2>Switch to another account</h2><ol class=\"steps\"><li><h3>End the current connection</h3><p>End the round and stop the game mode. If Studio is connecting to or connected to LIVE, click the top End button and wait for it to finish.</p></li><li><h3>Click Switch Account</h3><p>Open the top-right account menu and choose Switch Account to return to account selection.</p></li><li><h3>Select a saved account or add one</h3><p>Click a saved account to try signing in directly. For a new account, click Add another account and enter ID and Password. If a saved sign-in has expired, enter its password to continue.</p></li><li><h3>Check the new account setup</h3><p>Confirm Active Profile, Cast roster, selected players, gifts and the OBS overlay before reconnecting LIVE for that account.</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-menu-full.png\" data-caption=\"Account menu reference: Cast Settings and Switch Account are in this menu\" aria-label=\"Enlarge: Account menu reference: Cast Settings and Switch Account are in this menu\"><img src=\"assets/cast-menu-full.png\" alt=\"Account menu reference: Cast Settings and Switch Account are in this menu\" loading=\"lazy\"></button><figcaption><span>Account menu reference: Cast Settings and Switch Account are in this menu</span><span></span></figcaption></figure><details><summary>What if sign-in fails?</summary><p>Check your ID and password. If Authentication service is unavailable appears, check the network and retry later. Contact your account administrator if it continues.</p></details><details><summary>What does Log Out do?</summary><p>Log Out in the account menu signs out of the current Studio session. To move to another account, use Switch Account.</p></details><p class=\"completion-check\"><span>Check before continuing: </span>Active Profile shows the account you intend to use for this LIVE.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/account-picker-full.png\" data-caption=\"Switch Account opens the saved account list. Add another account opens the ID and password form.\" aria-label=\"Switch Account opens the saved account list. Add another account opens the ID and password form.\"><img src=\"assets/account-picker-full.png\" alt=\"Switch Account opens the saved account list. Add another account opens the ID and password form.\" loading=\"lazy\"></button><figcaption><span>Switch Account opens the saved account list. Add another account opens the ID and password form.</span><span></span></figcaption></figure><p>After Log Out, the account can remain in the list, but its saved sign-in has ended and a password is required. Switch Account keeps a valid saved sign-in available for quick return. An expired sign-in still needs a password.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">ACCOUNT</div><h1>登录与切换账号</h1><p class=\"lead\">先登录 Studio，再确认右上角显示的是本场直播使用的账号。</p></div><h2>第一次登录</h2><ol class=\"steps\"><li><h3>打开登录页</h3><p>启动 Studio。在 ID 输入你的 Studio 账号，在 Password 输入密码，点击 Sign In。</p></li><li><h3>检查当前账号</h3><p>进入首页后，点击右上角账号，核对 Active Profile。Studio 登录账号与之后连接的 TikTok LIVE 是两个环节。</p></li></ol><h2>切换到另一个账号</h2><ol class=\"steps\"><li><h3>先结束当前连接</h3><p>结束当前游戏并停止模式；如 Studio 正在连接或已连接 LIVE，先点击顶部 End，等待结束。</p></li><li><h3>点击 Switch Account</h3><p>打开右上角账号菜单，选择 Switch Account，返回账号选择页。</p></li><li><h3>选已有账号或添加账号</h3><p>点击已保存的账号可尝试直接登录。要登录新账号，点 Add another account，再填写 ID 和 Password。保存登录已过期时，输入密码后继续。</p></li><li><h3>重新检查配置</h3><p>切换后核对 Active Profile、Cast 名单、参赛成员、礼物与 OBS 画面，再重新连接该账号的 LIVE。</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-menu-full.png\" data-caption=\"账号菜单参考图 Cast Settings 与 Switch Account 在同一菜单中\" aria-label=\"Enlarge: 账号菜单参考图 Cast Settings 与 Switch Account 在同一菜单中\"><img src=\"assets/cast-menu-full.png\" alt=\"账号菜单参考图 Cast Settings 与 Switch Account 在同一菜单中\" loading=\"lazy\"></button><figcaption><span>账号菜单参考图 Cast Settings 与 Switch Account 在同一菜单中</span><span></span></figcaption></figure><details><summary>登录失败怎么办？</summary><p>核对 ID 与密码。出现 Authentication service is unavailable 时，先检查网络，稍后重试；仍失败时联系账号管理员。</p></details><details><summary>Log Out 是什么？</summary><p>在账号菜单中点击 Log Out，可退出当前 Studio 登录。要改用另一个账号，通常直接使用 Switch Account 更方便。</p></details><p class=\"completion-check\"><span>完成后检查：</span>右上角 Active Profile 是本场直播要使用的账号。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/account-picker-full.png\" data-caption=\"Switch Account 打开已保存账号列表；Add another account 打开 ID 和密码输入页。\" aria-label=\"Switch Account 打开已保存账号列表；Add another account 打开 ID 和密码输入页。\"><img src=\"assets/account-picker-full.png\" alt=\"Switch Account 打开已保存账号列表；Add another account 打开 ID 和密码输入页。\" loading=\"lazy\"></button><figcaption><span>Switch Account 打开已保存账号列表；Add another account 打开 ID 和密码输入页。</span><span></span></figcaption></figure><p>Log Out 后，账号可能仍在列表中，但原登录已结束，再次进入需要密码。Switch Account 保留有效登录，便于快速切回；登录过期时仍需重新输入密码。</p>"}},"cast":{"title":{"en":"Add Cast members","zh":"添加 Cast 成员"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">FIRST SESSION</div><h1>Add Cast members</h1><p class=\"lead\">Cast members are the people who take part in your games. Create the roster first, then select participants inside each game.</p></div><h2>1 Open Cast Settings</h2><p>Open the top-right account menu. Under the active profile, click <code>Cast Settings</code>.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-menu-full.png\" data-caption=\"Where to add members: account menu → Cast Settings\" aria-label=\"Enlarge: Where to add members: account menu → Cast Settings\"><img src=\"assets/cast-menu-full.png\" alt=\"Where to add members: account menu → Cast Settings\" loading=\"lazy\"></button><figcaption><span>Where to add members: account menu → Cast Settings</span><span></span></figcaption></figure><h2>2 Enter the member details</h2><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-filled-full.png\" data-caption=\"Added Cast members: h_001022 has a retrieved avatar; test1 and test2 use nickname avatars\" aria-label=\"Enlarge: Added Cast members: h_001022 has a retrieved avatar; test1 and test2 use nickname avatars\"><img src=\"assets/cast-filled-full.png\" alt=\"Added Cast members: h_001022 has a retrieved avatar; test1 and test2 use nickname avatars\" loading=\"lazy\"></button><figcaption><span>Added Cast members: h_001022 has a retrieved avatar; test1 and test2 use nickname avatars</span><span></span></figcaption></figure><ol class=\"steps\"><li><h3>Enter the TikTok username</h3><p>Use TikTok @username, not the display name on the profile. The screenshot uses h_001022 for account lookup; test1 and test2 are nickname-only examples.</p></li><li><h3>Click Find</h3><p>Check the returned avatar and name. If the lookup fails, you can enter Cast Nickname manually before adding.</p></li><li><h3>Enter Cast Nickname and click Add Cast</h3><p>This name appears in the game. After adding, confirm the member appears in the Cast Members list on the right.</p></li></ol><details><summary>Why can’t I edit members?</summary><p>Stop the running game mode before opening Cast Settings. Member settings may be locked while a mode is running.</p></details><p class=\"completion-check\"><span>Check before continuing: </span>The required members appear in Cast Members. Select the participants again inside the game you choose.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">首次使用</div><h1>添加 Cast 成员</h1><p class=\"lead\">Cast 就是参与游戏的成员。先建立名单，之后再到每个玩法中选择谁上场。</p></div><h2>1. 找到 Cast Settings</h2><p>点击右上角账号，在当前资料（Active Profile）下打开 <code>Cast Settings</code>。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-menu-full.png\" data-caption=\"添加入口：右上角账号 → Cast Settings\" aria-label=\"放大：添加入口：右上角账号 → Cast Settings\"><img src=\"assets/cast-menu-full.png\" alt=\"添加入口：右上角账号 → Cast Settings\" loading=\"lazy\"></button><figcaption><span>添加入口：右上角账号 → Cast Settings</span><span></span></figcaption></figure><h2>2. 填写成员资料</h2><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/cast-filled-full.png\" data-caption=\"添加完成后的成员名单：h_001022 已获取头像，test1、test2 使用昵称头像\" aria-label=\"放大：添加完成后的成员名单：h_001022 已获取头像，test1、test2 使用昵称头像\"><img src=\"assets/cast-filled-full.png\" alt=\"添加完成后的成员名单：h_001022 已获取头像，test1、test2 使用昵称头像\" loading=\"lazy\"></button><figcaption><span>添加完成后的成员名单：h_001022 已获取头像，test1、test2 使用昵称头像</span><span></span></figcaption></figure><ol class=\"steps\"><li><h3>输入 TikTok 用户名</h3><p>在 TikTok @username 中填写成员的 TikTok 用户名，不要填主页显示昵称。截图用 h_001022 演示查找，test1、test2 是手动添加的昵称示例。</p></li><li><h3>点击 Find</h3><p>查找成员资料，检查头像与昵称是否正确。查找失败时，可手动填写 Cast Nickname 后添加。</p></li><li><h3>填写 Cast Nickname，点击 Add Cast</h3><p>这是该成员在游戏中使用的名字。成功后，成员应出现在右侧 Cast Members 列表中。</p></li></ol><details><summary>为什么不能添加或编辑成员？</summary><p>先停止正在运行的游戏模式，再打开 Cast Settings。运行中成员设置可能锁定。</p></details><p class=\"completion-check\"><span>完成后检查：</span>需要的成员都出现在 Cast Members 中；下一步还要在具体玩法中选择参赛成员。</p>"}},"camera":{"title":{"en":"Connect camera and OBS","zh":"连接摄像头与 OBS"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">FIRST SESSION</div><h1>Connect camera and OBS</h1><p class=\"lead\">Connect the camera feed to Studio, then add the separate interactive overlay to OBS.</p></div><h2>1 Show the camera in Studio</h2><ol class=\"steps\"><li><h3>Prepare the scene in OBS</h3><p>Set up your camera and scene, then start OBS Virtual Camera. You may also use an available physical camera.</p></li><li><h3>Select the source in Studio</h3><p>Click the gear next to Camera. In Camera Source, select OBS Virtual Camera or your camera.</p></li><li><h3>Check the center preview</h3><p>If the device is missing, click Refresh Sources. Continue when the video preview works.</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/camera-full.png\" data-caption=\"Camera Settings: select a source and refresh devices if needed\" aria-label=\"Enlarge: Camera Settings: select a source and refresh devices if needed\"><img src=\"assets/camera-full.png\" alt=\"Camera Settings: select a source and refresh devices if needed\" loading=\"lazy\"></button><figcaption><span>Camera Settings: select a source and refresh devices if needed</span><span></span></figcaption></figure><h2>2 Show game content in OBS</h2><ol class=\"steps\"><li><h3>Copy the overlay link</h3><p>Open the top-right Studio settings gear. Copy the OBS Overlay Runtime link.</p></li><li><h3>Add a Browser source in OBS</h3><p>Paste that link into an OBS Browser source. Match its dimensions to the final canvas, for example 1080 × 1920 for portrait video.</p></li><li><h3>Place it above the camera</h3><p>Keep the Browser source above the camera source. Start the chosen mode and check member cards, scores and timers in OBS.</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/overlay-link-full.png\" data-caption=\"Studio Settings: copy the OBS Overlay Runtime link from your own app\" aria-label=\"Enlarge: Studio Settings: copy the OBS Overlay Runtime link from your own app\"><img src=\"assets/overlay-link-full.png\" alt=\"Studio Settings: copy the OBS Overlay Runtime link from your own app\" loading=\"lazy\"></button><figcaption><span>Studio Settings: copy the OBS Overlay Runtime link from your own app</span><span></span></figcaption></figure><div class=\"note\">A localhost link works on the same computer. Copy the link from your own Studio; do not type the address from this screenshot.</div><p class=\"completion-check\"><span>Check before continuing: </span>The center preview shows video. When a mode runs, its members and scores appear in the OBS Browser source.</p><div class=\"note\"><strong>Why does the game not appear in OBS after starting?</strong> If you have clicked Play / Start / Start round but the game overlay does not appear in OBS, select the Streamplay Browser Source in OBS Sources, open Properties, and click Refresh cache of current page. Then check the overlay again. Refresh the Browser Source, not the camera source.</div>","zh":"<div class=\"hero\"><div class=\"eyebrow\">首次使用</div><h1>连接摄像头与 OBS</h1><p class=\"lead\">需要接好两条连接：摄像头画面进入 Studio，游戏叠加层进入 OBS。</p></div><h2>1. 让 Studio 看到摄像头</h2><ol class=\"steps\"><li><h3>在 OBS 准备画面</h3><p>选择摄像头、布置画面，再启动 OBS Virtual Camera（虚拟摄像头）。也可以使用可用的实体摄像头。</p></li><li><h3>在 Studio 选择来源</h3><p>点击左侧 Camera 旁的齿轮，在 Camera Source 选择 OBS Virtual Camera 或对应摄像头。</p></li><li><h3>检查中间预览</h3><p>找不到设备时点击 Refresh Sources。预览正常后，再继续接入互动叠加层。</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/camera-full.png\" data-caption=\"Camera Settings：选择摄像头来源，必要时刷新设备\" aria-label=\"放大：Camera Settings：选择摄像头来源，必要时刷新设备\"><img src=\"assets/camera-full.png\" alt=\"Camera Settings：选择摄像头来源，必要时刷新设备\" loading=\"lazy\"></button><figcaption><span>Camera Settings：选择摄像头来源，必要时刷新设备</span><span></span></figcaption></figure><h2>2. 让 OBS 显示互动内容</h2><ol class=\"steps\"><li><h3>复制叠加层链接</h3><p>点击 Studio 右上角设置齿轮，在 OBS Overlay Runtime 旁点击复制。</p></li><li><h3>在 OBS 添加浏览器源</h3><p>添加 Browser（浏览器）来源，粘贴刚复制的链接。尺寸与最终直播画布一致，例如竖屏 1080 × 1920。</p></li><li><h3>放在摄像头上层</h3><p>将浏览器来源放在摄像头来源上面；启动所选玩法后，检查成员卡、分数与倒计时是否正常显示。</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/overlay-link-full.png\" data-caption=\"Studio Settings：复制你自己软件里的 OBS Overlay Runtime 链接\" aria-label=\"放大：Studio Settings：复制你自己软件里的 OBS Overlay Runtime 链接\"><img src=\"assets/overlay-link-full.png\" alt=\"Studio Settings：复制你自己软件里的 OBS Overlay Runtime 链接\" loading=\"lazy\"></button><figcaption><span>Studio Settings：复制你自己软件里的 OBS Overlay Runtime 链接</span><span></span></figcaption></figure><div class=\"note\">截图中的 localhost 链接只适用于同一台电脑。<strong>请复制你自己 Studio 显示的链接</strong>，不要照抄截图地址。</div><p class=\"completion-check\"><span>完成后检查：</span>Studio 中间能看到画面。玩法启动后，OBS 浏览器源能显示该玩法的成员与分数。</p><div class=\"note\"><strong>点击开始后，OBS 为什么没有显示游戏画面？</strong> 如果已点击 Play / Start / Start round，但 OBS 中没有显示互动叠加层，先在 OBS 的“来源”中选中 Streamplay 对应的浏览器源，打开“属性”，点击“刷新当前页面的缓存”（Refresh cache of current page），再检查画面。这里刷新的是浏览器源，不是摄像头源。</div>"}},"modes":{"title":{"en":"Choose a game","zh":"选择一种玩法"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">FIRST SESSION</div><h1>Choose a game</h1><p class=\"lead\">Try Group Sticker first to learn how members and gifts match. Then explore timed rounds and queue rotation.</p></div><div class=\"mode-list\"><a class=\"mode-row\" href=\"#sticker\"><span class=\"mode-num\">01</span><div><strong>Group Sticker</strong><p>Member cards with continuous scoring</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#group\"><span class=\"mode-num\">02</span><div><strong>Group PK</strong><p>Members compete together in a timed round</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#one\"><span class=\"mode-num\">03</span><div><strong>1v1 PK</strong><p>Two players compete and the winner stays</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#solo\"><span class=\"mode-num\">04</span><div><strong>Solo Stage</strong><p>Members take turns on a timed solo stage</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#multi\"><span class=\"mode-num\">05</span><div><strong>Multi PK</strong><p>Multiple players compete with a bench queue</p></div><span class=\"arrow\">↗</span></a></div><h2>The usual sequence</h2><ol class=\"steps\"><li><h3>Choose a mode and open settings</h3><p>Click a mode card, then its settings gear. Select members, set the timer where available, and map gifts in modes with Gift Mapping. Solo Stage does not need representative gifts for members.</p></li><li><h3>Save the setup</h3><p>Click Save Settings. Open Map representative gifts from the contents if you need help.</p></li><li><h3>Start when LIVE is ready</h3><p>Confirm the broadcast is live and Studio is connected, then follow Start your first interaction to start the mode and round.</p></li></ol>","zh":"<div class=\"hero\"><div class=\"eyebrow\">首次使用</div><h1>选择一种玩法</h1><p class=\"lead\">第一次使用可以先试 Group Sticker。熟悉成员和礼物的对应关系后，再使用计时与轮换玩法。</p></div><div class=\"mode-list\"><a class=\"mode-row\" href=\"#sticker\"><span class=\"mode-num\">01</span><div><strong>Group Sticker · 成员贴纸</strong><p>每个成员一张礼物卡，持续累计分数。</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#group\"><span class=\"mode-num\">02</span><div><strong>Group PK · 团体计时 PK</strong><p>多位成员同时比赛，在一段时间内比积分。</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#one\"><span class=\"mode-num\">03</span><div><strong>1v1 PK · 双人擂台</strong><p>两人对战，赢家留台，下一位接着挑战。</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#solo\"><span class=\"mode-num\">04</span><div><strong>Solo Stage · 单人舞台</strong><p>成员依次上场，进行个人目标或自由计时互动。</p></div><span class=\"arrow\">↗</span></a><a class=\"mode-row\" href=\"#multi\"><span class=\"mode-num\">05</span><div><strong>Multi PK · 多人轮换 PK</strong><p>多人同台，分数最低者与候场队列轮换。</p></div><span class=\"arrow\">↗</span></a></div><h2>大多数玩法都按这个顺序</h2><ol class=\"steps\"><li><h3>选择玩法并打开设置</h3><p>点击模式卡片，再点击模式旁的齿轮选择成员。有计时的玩法设置时长；有 Gift Mapping 的玩法还要配置礼物。Solo Stage 不需要成员代表礼物。</p></li><li><h3>保存设置</h3><p>点击 Save Settings。需要时打开左侧“绑定代表礼物”图解。</p></li><li><h3>准备好后再开始</h3><p>确认直播已开播且 Studio 已连接，再按“开始第一场互动”章节启动模式与本局。</p></li></ol>"}},"gifts":{"title":{"en":"Map representative gifts","zh":"绑定代表礼物"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GIFT MAPPING</div><h1>Map representative gifts</h1><p class=\"lead\">In modes with Gift Mapping, select a representative gift for each member. Scoring follows the active game’s rules.</p></div><ol class=\"steps\"><li><h3>Open the game settings</h3><p>Find Gift Mapping and check the member’s name.</p></li><li><h3>Click the gift next to a member</h3><p>Search in Select Gift. Check the icon, name and point value.</p></li><li><h3>Save the completed setup</h3><p>Map all participants, including waiting members where required, then click Save Settings.</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gift-mapping-full.png\" data-caption=\"Gift Mapping: each row pairs a member with a gift\" aria-label=\"Enlarge: Gift Mapping: each row pairs a member with a gift\"><img src=\"assets/gift-mapping-full.png\" alt=\"Gift Mapping: each row pairs a member with a gift\" loading=\"lazy\"></button><figcaption><span>Gift Mapping: each row pairs a member with a gift</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gift-select-full.png\" data-caption=\"Select Gift: an example search for Rose\" aria-label=\"Enlarge: Select Gift: an example search for Rose\"><img src=\"assets/gift-select-full.png\" alt=\"Select Gift: an example search for Rose\" loading=\"lazy\"></button><figcaption><span>Select Gift: an example search for Rose</span><span></span></figcaption></figure><div class=\"note\">In Multi PK, every on-stage and bench member needs a unique representative gift. Check the mapping before going live.</div><details><summary>What happens to other gifts?</summary><p>You can enable Gifter Binding in Modes settings when needed. Once a viewer has a member binding, it provides fallback attribution for later unmatched gifts. Review gifts already marked unallocated in the LIVE log.</p></details><p class=\"completion-check\"><span>Check before continuing: </span>Each member matches the intended gift icon and name, and settings are saved. In Multi PK, bench members are configured too.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GIFT MAPPING</div><h1>绑定代表礼物</h1><p class=\"lead\">在有 Gift Mapping 的玩法中，为成员选择代表礼物。观众送出对应礼物时，系统才能按该玩法规则给成员加分。</p></div><ol class=\"steps\"><li><h3>打开玩法设置</h3><p>找到 Gift Mapping，先确认成员姓名或昵称。</p></li><li><h3>点击成员旁的礼物</h3><p>在 Select Gift 窗口搜索礼物名，并核对图标、名称和分值。</p></li><li><h3>选好后保存</h3><p>完成所有参赛成员的礼物配置，点击 Save Settings。需要轮换的玩法也要检查候场成员。</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gift-mapping-full.png\" data-caption=\"Gift Mapping：每行对应一名成员及其代表礼物\" aria-label=\"放大：Gift Mapping：每行对应一名成员及其代表礼物\"><img src=\"assets/gift-mapping-full.png\" alt=\"Gift Mapping：每行对应一名成员及其代表礼物\" loading=\"lazy\"></button><figcaption><span>Gift Mapping：每行对应一名成员及其代表礼物</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gift-select-full.png\" data-caption=\"Select Gift：搜索并核对礼物；这里以 Rose 搜索为例\" aria-label=\"放大：Select Gift：搜索并核对礼物；这里以 Rose 搜索为例\"><img src=\"assets/gift-select-full.png\" alt=\"Select Gift：搜索并核对礼物；这里以 Rose 搜索为例\" loading=\"lazy\"></button><figcaption><span>Select Gift：搜索并核对礼物；这里以 Rose 搜索为例</span><span></span></figcaption></figure><div class=\"note\">Multi PK 的上场与候场成员都需要绑定<strong>唯一代表礼物</strong>。其他玩法也应在开场前检查对应关系。</div><details><summary>观众送了其他礼物怎么办？</summary><p>可以按实际需求开启 Modes 设置里的 Gifter Binding。它用于观众归属绑定后，对后续未匹配礼物进行归属兜底。已出现的未分配礼物，请到直播记录里检查与分配。</p></details><p class=\"completion-check\"><span>完成后检查：</span>成员、礼物图标和名称逐一对应，设置已保存。Multi PK 的候场成员也已配置。</p>"}},"live":{"title":{"en":"Start your first interaction","zh":"开始第一场互动"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">FIRST SESSION</div><h1>Start your first interaction</h1><p class=\"lead\">Once members, video and game settings are ready, start in this order.</p></div><ol class=\"steps\"><li><h3>Go live in your streaming software</h3><p>Start TikTok LIVE with your streaming software and confirm the room is online.</p></li><li><h3>Click the top Start button in Studio</h3><p>Connect to the current TikTok LIVE. Check that LIVE Chat and statistics begin updating.</p></li><li><h3>Start the chosen mode</h3><p>Click ▶ Play. In timed modes, also click Start round or Start. Check the game overlay in OBS.</p></li><li><h3>Verify a real interaction</h3><p>Check the viewer, gift, assigned member and score before continuing the activity.</p></li></ol><div class=\"note\">The top Start button does not start a broadcast. It connects LIVE data. Go live in your streaming software first.</div><h2>Quick check before starting</h2><table class=\"simple-table\"><tbody><tr><td>Members</td><td>Added to Cast and selected in the game.</td></tr><tr><td>Gifts</td><td>Mapped correctly, including any waiting members.</td></tr><tr><td>Video</td><td>Camera preview works and OBS shows the game overlay.</td></tr><tr><td>LIVE</td><td>The room is live, Studio is connected and interactions arrive.</td></tr></tbody></table>","zh":"<div class=\"hero\"><div class=\"eyebrow\">首次使用</div><h1>开始第一场互动</h1><p class=\"lead\">前面的成员、画面和玩法都准备好后，按下面顺序开始。</p></div><ol class=\"steps\"><li><h3>在直播软件正式开播</h3><p>先使用你的直播软件开始 TikTok LIVE，确认直播间已上线。</p></li><li><h3>点击 Studio 顶部 Start</h3><p>连接当前 TikTok LIVE。观察右侧 LIVE Chat 与直播数据是否开始更新。</p></li><li><h3>启动所选玩法</h3><p>点击模式的 ▶ Play。计时模式再点击 Start round / Start，检查 OBS 叠加层是否显示。</p></li><li><h3>确认一次真实互动</h3><p>核对观众、礼物、归属成员与分数是否一致，再正式推进活动。</p></li></ol><div class=\"note\"><strong>顶部 Start 不会替你开播。</strong>它连接直播数据；开播仍需要在实际直播软件中完成。</div><h2>开场前快速检查</h2><table class=\"simple-table\"><tbody><tr><td>成员</td><td>已添加，并在玩法中勾选。</td></tr><tr><td>礼物</td><td>图标和成员对应正确，候场成员也已检查。</td></tr><tr><td>画面</td><td>Studio 有预览，OBS 有互动叠加层。</td></tr><tr><td>直播</td><td>平台已开播，Studio 已连接，互动数据能收到。</td></tr></tbody></table>"}},"sticker":{"title":{"en":"Group Sticker","zh":"Group Sticker"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Group Sticker</h1><p class=\"lead\">Member cards with continuous scoring</p></div><h2>When to use it</h2><p>For ongoing group interaction: member gift cards keep scoring without timed rounds. Viewers support a member with that member’s mapped gift.</p><h2>How to set up</h2><ol class=\"steps\"><li><h3>Select members</h3><p>Open the game settings and choose the Cast members to display.</p></li><li><h3>Map their gifts</h3><p>Use Gift Mapping to choose each member’s gift, then click Save Settings.</p></li></ol><p><a href=\"#gifts\">Need help choosing gifts? Open the gift mapping guide →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/sticker-settings.png\" data-caption=\"Group Sticker settings\" aria-label=\"Enlarge: Group Sticker settings\"><img src=\"assets/sticker-settings.png\" alt=\"Group Sticker settings\" loading=\"lazy\"></button><figcaption><span>Group Sticker settings</span><span></span></figcaption></figure><p><strong>Placement</strong> — Drag the overlay to move it; drag its corner to resize it. Reset restores the placement.</p><p><strong>Cast Selection</strong> — Select the members who will appear in this game.</p><p><strong>Gift Mapping</strong> — Click each member’s gift to choose the representative gift, then Save Settings.</p><h2>How to start</h2><p class=\"preflight\"><strong>Before starting: </strong>Check the displayed members, each mapped gift and the overlay position in OBS. This mode has no round timer.</p><p>Return to the mode panel and click ▶ Play. Check the member scores when mapped gifts arrive.</p><h2>How to end</h2><p>Stop Group Sticker from the mode panel when finished. There is no separate round to end.</p><h2>How to continue</h2><p>Group Sticker has no next round. Keep the mode running to continue. To change members or gifts, stop it, update and save settings, then click ▶ Play again.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Group Sticker · 成员贴纸</h1><p class=\"lead\">每个成员一张礼物卡，持续累计分数。</p></div><h2>适合什么场景</h2><p>适合日常团播互动：成员礼物卡持续累计分数，不分计时回合。观众送出对应礼物，支持指定成员。</p><h2>怎么设置</h2><ol class=\"steps\"><li><h3>选择成员</h3><p>打开模式设置，勾选要展示的 Cast。</p></li><li><h3>设置代表礼物</h3><p>在 Gift Mapping 中，为成员选择对应礼物，点击 Save Settings。</p></li></ol><p><a href=\"#gifts\" style=\"color:var(--pink);font-size:13px\">不会选礼物？查看礼物绑定图解 →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/sticker-settings.png\" data-caption=\"Group Sticker 设置界面\" aria-label=\"放大：Group Sticker 设置界面\"><img src=\"assets/sticker-settings.png\" alt=\"Group Sticker 设置界面\" loading=\"lazy\"></button><figcaption><span>Group Sticker 设置界面</span><span></span></figcaption></figure><p><strong>Placement</strong> — 拖动叠层调整位置，拖动角落调整大小；Reset 重置位置。</p><p><strong>Cast Selection</strong> — 勾选本玩法需要显示的成员。</p><p><strong>Gift Mapping</strong> — 点击每名成员对应的礼物，选择代表礼物，再点 Save Settings。</p><h2>怎么开始</h2><p class=\"preflight\"><strong>开场前检查：</strong>确认展示成员、每位成员的代表礼物和 OBS 叠加层位置；此模式无需设置回合计时。</p><p>回到模式面板，点击 ▶ Play。收到对应礼物后查看成员分数。</p><h2>怎么结束</h2><p>需要结束时，在模式面板停止 Group Sticker。它没有单独的回合结束步骤。</p><h2>怎么下一轮</h2><p>Group Sticker 没有“下一局”。想继续互动就保持模式运行；需要更换成员或礼物时，先停止模式，修改并保存设置，再点击 ▶ Play。</p>"}},"group":{"title":{"en":"Group PK","zh":"Group PK"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Group PK</h1><p class=\"lead\">Members compete together in a timed round</p></div><h2>When to use it</h2><p>For timed contests with several members competing together. Viewers send mapped gifts, and the round scores show the result.</p><h2>How to set up</h2><ol class=\"steps\"><li><h3>Set the round time</h3><p>Open settings, select members and enter the duration in seconds.</p></li><li><h3>Map gifts and save</h3><p>Choose representative gifts in Gift Mapping, then click Save Settings.</p></li></ol><p><a href=\"#gifts\">Need help choosing gifts? Open the gift mapping guide →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/group-pk-settings.png\" data-caption=\"Group PK settings\" aria-label=\"Enlarge: Group PK settings\"><img src=\"assets/group-pk-settings.png\" alt=\"Group PK settings\" loading=\"lazy\"></button><figcaption><span>Group PK settings</span><span></span></figcaption></figure><p><strong>Round Timer</strong> — Set the round length in seconds.</p><p><strong>Gift Background / Opacity</strong> — Adjust the background colour and opacity behind gift icons.</p><p><strong>Cast Selection / Gift Mapping</strong> — Select members and check the gifts shown for each member.</p><h2>How to start</h2><p class=\"preflight\"><strong>Before starting: </strong>Check participants, mapped gifts, Round Timer and the OBS overlay before starting.</p><p>Click ▶ Play to enter the mode, then Start round to begin the countdown.</p><h2>How to end</h2><p>Let the timer finish, or click End round, then review the result.</p><h2>How to continue</h2><p>Wait for the 8-second buffer, then click Start round. Members are not automatically eliminated or replaced under Multi PK rules.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Group PK · 团体计时 PK</h1><p class=\"lead\">多位成员同时比赛，在一段时间内比积分。</p></div><h2>适合什么场景</h2><p>适合多位成员同时进行限时积分赛。观众通过成员代表礼物支持，按本局分数查看结果。</p><h2>怎么设置</h2><ol class=\"steps\"><li><h3>设置一局时长</h3><p>打开模式设置，选择成员并填写比赛秒数。</p></li><li><h3>绑定礼物并保存</h3><p>在 Gift Mapping 中设置成员代表礼物，点击 Save Settings。</p></li></ol><p><a href=\"#gifts\" style=\"color:var(--pink);font-size:13px\">不会选礼物？查看礼物绑定图解 →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/group-pk-settings.png\" data-caption=\"Group PK 设置界面\" aria-label=\"放大：Group PK 设置界面\"><img src=\"assets/group-pk-settings.png\" alt=\"Group PK 设置界面\" loading=\"lazy\"></button><figcaption><span>Group PK 设置界面</span><span></span></figcaption></figure><p><strong>Round Timer</strong> — 设置每一轮的秒数。</p><p><strong>Gift Background / Opacity</strong> — 调整礼物图标底板颜色与透明度。</p><p><strong>Cast Selection / Gift Mapping</strong> — 勾选成员，逐一检查各成员对应的礼物。</p><h2>怎么开始</h2><p class=\"preflight\"><strong>开场前检查：</strong>确认参赛成员、代表礼物、Round Timer 和 OBS 画面，再开始本局。</p><p>点击 ▶ Play 进入模式，再点击 Start round 开始倒计时。</p><h2>怎么结束</h2><p>倒计时结束，或点击 End round，结束本局并查看结果。</p><h2>怎么下一轮</h2><p>等待 8 秒缓冲结束，再点击 Start round 开始下一局。成员不会按 Multi PK 的规则自动淘汰或替换。</p>"}},"one":{"title":{"en":"1v1 PK","zh":"1v1 PK"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>1v1 PK</h1><p class=\"lead\">Two players compete and the winner stays</p></div><h2>When to use it</h2><p>For head-to-head contests with a waiting queue. The first two members take LEFT / RIGHT; viewers support them with mapped gifts, and the winner stays.</p><h2>How to set up</h2><ol class=\"steps\"><li><h3>Select participants</h3><p>Open settings and select the competing and waiting members.</p></li><li><h3>Set time and gifts</h3><p>Set the round duration and map each participant’s gift. Click Save Settings.</p></li></ol><p><a href=\"#gifts\">Need help choosing gifts? Open the gift mapping guide →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/1v1-settings.png\" data-caption=\"1v1 PK settings\" aria-label=\"Enlarge: 1v1 PK settings\"><img src=\"assets/1v1-settings.png\" alt=\"1v1 PK settings\" loading=\"lazy\"></button><figcaption><span>1v1 PK settings</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/1v1-settings-bottom.png\" data-caption=\"1v1 PK settings 2 of 2: member gifts and Save Settings\" aria-label=\"1v1 PK settings 2 of 2: member gifts and Save Settings\"><img src=\"assets/1v1-settings-bottom.png\" alt=\"1v1 PK settings 2 of 2: member gifts and Save Settings\" loading=\"lazy\"></button><figcaption><span>1v1 PK settings 2 of 2: member gifts and Save Settings</span><span></span></figcaption></figure><p><strong>Round Timer</strong> — Set each matchup’s length in seconds.</p><p><strong>Divider Style</strong> — Choose None, White or Fire for the divider.</p><p><strong>Losing Side Effect</strong> — Choose the visual effect for the losing side.</p><p><strong>Scoreboard Style</strong> — Choose Current, Prism metal or Minimal neon.</p><p><strong>Cast Selection / Creator Gift Mapping</strong> — Select participants and configure each member’s gifts. The first two in the queue play first.</p><h2>How to start</h2><p class=\"preflight\"><strong>Before starting: </strong>Check ROUND QUEUE order, LEFT / RIGHT members, mapped gifts, Round Timer and the OBS overlay.</p><p>Save and click ▶ Play. Drag members in ROUND QUEUE on the mode panel; the first two play first. Check LEFT / RIGHT, then click Start round.</p><h2>How to end</h2><p>Let the timer finish, or click End round, then review the matchup result.</p><h2>How to continue</h2><p>The winner stays on the same side, the loser moves to the queue end, and the next waiting member enters. Check the matchup, then click Start round. A tie keeps the matchup; with only two members there is no replacement.</p><div class=\"note\">Check the names on LEFT and RIGHT so your spoken instructions match the gift mapping.</div>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>1v1 PK · 双人擂台</h1><p class=\"lead\">两人对战，赢家留台，下一位接着挑战。</p></div><h2>适合什么场景</h2><p>适合双人擂台和排队挑战。队列前两位进入 LEFT / RIGHT，观众送对应礼物支持；获胜者留台。</p><h2>怎么设置</h2><ol class=\"steps\"><li><h3>选择参赛成员</h3><p>打开设置，勾选参与对战与候场的成员。</p></li><li><h3>设置比赛时长和礼物</h3><p>为参赛成员绑定代表礼物，检查后点击 Save Settings。</p></li></ol><p><a href=\"#gifts\" style=\"color:var(--pink);font-size:13px\">不会选礼物？查看礼物绑定图解 →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/1v1-settings.png\" data-caption=\"1v1 PK 设置界面\" aria-label=\"放大：1v1 PK 设置界面\"><img src=\"assets/1v1-settings.png\" alt=\"1v1 PK 设置界面\" loading=\"lazy\"></button><figcaption><span>1v1 PK 设置界面</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/1v1-settings-bottom.png\" data-caption=\"1v1 PK 设置 2/2：各成员礼物与 Save Settings\" aria-label=\"1v1 PK 设置 2/2：各成员礼物与 Save Settings\"><img src=\"assets/1v1-settings-bottom.png\" alt=\"1v1 PK 设置 2/2：各成员礼物与 Save Settings\" loading=\"lazy\"></button><figcaption><span>1v1 PK 设置 2/2：各成员礼物与 Save Settings</span><span></span></figcaption></figure><p><strong>Round Timer</strong> — 设置每次对战的时长，单位秒。</p><p><strong>Divider Style</strong> — 选择无分隔、白色分隔或火焰分隔。</p><p><strong>Losing Side Effect</strong> — 选择落后一侧的视觉效果。</p><p><strong>Scoreboard Style</strong> — 选择 Current、Prism metal 或 Minimal neon 记分板外观。</p><p><strong>Cast Selection / Creator Gift Mapping</strong> — 选择参赛成员，设置各成员礼物；队列前两名先上场。</p><h2>怎么开始</h2><p class=\"preflight\"><strong>开场前检查：</strong>确认 ROUND QUEUE 顺序、LEFT / RIGHT 成员、各成员礼物、Round Timer 和 OBS 画面。</p><p>保存后点击 ▶ Play，在模式面板的 ROUND QUEUE 中拖动排好顺序，前两位先上场。确认 LEFT / RIGHT 后点击 Start round。</p><h2>怎么结束</h2><p>倒计时结束，或点击 End round，结束当前对战并查看结果。</p><h2>怎么下一轮</h2><p>获胜者留在原来一侧，败者回到队尾，下一位候场成员补位；确认对阵后点击 Start round。平局保留原对阵，只有两名成员时不换人。</p><div class=\"note\">开始前看清 LEFT / RIGHT 对应的成员，避免口播与礼物对应关系弄反。</div>"}},"solo":{"title":{"en":"Solo Stage","zh":"Solo Stage"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Solo Stage</h1><p class=\"lead\">Members take turns on a timed solo stage</p></div><h2>When to use it</h2><p>For solo performances or target challenges. One member takes the stage at a time and receives eligible support. Choose Target or Freedom.</p><h2>How to set up</h2><ol class=\"steps\"><li><h3>Choose the format and queue</h3><p>Select Target or Freedom and arrange the member order.</p></li><li><h3>Set the time and display</h3><p>For Target, set target A below target B. Choose Original or Avatar as needed. Freedom also uses a timer.</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/solo-settings.png\" data-caption=\"Solo Stage settings\" aria-label=\"Enlarge: Solo Stage settings\"><img src=\"assets/solo-settings.png\" alt=\"Solo Stage settings\" loading=\"lazy\"></button><figcaption><span>Solo Stage settings</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/solo-freedom-settings.png\" data-caption=\"Solo Stage: Freedom and Avatar settings\" aria-label=\"Solo Stage: Freedom and Avatar settings\"><img src=\"assets/solo-freedom-settings.png\" alt=\"Solo Stage: Freedom and Avatar settings\" loading=\"lazy\"></button><figcaption><span>Solo Stage: Freedom and Avatar settings</span><span></span></figcaption></figure><p><strong>Cast Selection</strong> — Select the members who will take turns.</p><p><strong>Solo Type</strong> — Target shows target milestones; Freedom has no target milestones. Both use a timer.</p><p><strong>Overlay Style</strong> — Choose Original or Avatar.</p><p><strong>Timer / Target A / Target B</strong> — Set seconds. In Target mode, set A lower than B.</p><h2>How to start</h2><p class=\"preflight\"><strong>Before starting: </strong>Check the active member, queue order, timer and OBS overlay. In Target mode, check that A is lower than B.</p><p>Save settings, click ▶ Play, then Start for the active member.</p><h2>How to end</h2><p>Let the timer finish or end the round manually. The result stays visible; reaching a target does not change the active member.</p><h2>How to continue</h2><p>Click Start again to rotate to the next queued member and begin the next round. End the current round before changing settings.</p>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Solo Stage · 单人舞台</h1><p class=\"lead\">成员依次上场，进行个人目标或自由计时互动。</p></div><h2>适合什么场景</h2><p>适合成员轮流进行个人表演或目标挑战。每次一人上场，有效支持计入当前成员；可选 Target 或 Freedom。</p><h2>怎么设置</h2><ol class=\"steps\"><li><h3>选择玩法和成员</h3><p>在设置中选择 Target 或 Freedom，排好成员出场顺序。</p></li><li><h3>设置时间与展示</h3><p>Target 需要设置目标，A 小于 B；按需要选择 Original / Avatar 展示。Freedom 也有倒计时。</p></li></ol><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/solo-settings.png\" data-caption=\"Solo Stage 设置界面\" aria-label=\"放大：Solo Stage 设置界面\"><img src=\"assets/solo-settings.png\" alt=\"Solo Stage 设置界面\" loading=\"lazy\"></button><figcaption><span>Solo Stage 设置界面</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/solo-freedom-settings.png\" data-caption=\"Solo Stage：Freedom 与 Avatar 设置\" aria-label=\"Solo Stage：Freedom 与 Avatar 设置\"><img src=\"assets/solo-freedom-settings.png\" alt=\"Solo Stage：Freedom 与 Avatar 设置\" loading=\"lazy\"></button><figcaption><span>Solo Stage：Freedom 与 Avatar 设置</span><span></span></figcaption></figure><p><strong>Cast Selection</strong> — 选择轮流上场的成员。</p><p><strong>Solo Type</strong> — Target 显示目标分数；Freedom 不设目标分数，两者都有计时。</p><p><strong>Overlay Style</strong> — 选择 Original 或 Avatar 显示样式。</p><p><strong>Timer / Target A / Target B</strong> — 设置回合秒数；Target 模式下设置目标 A、B，且 A 小于 B。</p><h2>怎么开始</h2><p class=\"preflight\"><strong>开场前检查：</strong>确认当前上台成员、出场顺序、计时和 OBS 画面；Target 模式还要检查目标 A 小于 B。</p><p>保存后点击 ▶ Play，再点击 Start，当前成员开始本轮。</p><h2>怎么结束</h2><p>倒计时结束或手动结束本轮后，结果会保留在画面上。达到目标不会自动换人。</p><h2>怎么下一轮</h2><p>再次点击 Start，队列才轮到下一名成员并开始新一轮。要改设置，先结束当前回合。</p>"}},"multi":{"title":{"en":"Multi PK","zh":"Multi PK"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Multi PK</h1><p class=\"lead\">Multiple players compete with a bench queue</p></div><h2>When to use it</h2><p>For group contests with a rotating bench. Viewers send mapped gifts; round results and the bench queue determine who leaves and who enters.</p><h2>How to set up</h2><ol class=\"steps\"><li><h3>Set the stage and bench</h3><p>Set On-stage count from 2 to 21. Select exactly that many members in On Stage and place waiting members in Bench Queue.</p></li><li><h3>Set time and unique gifts</h3><p>Choose 10–3600 seconds. Every on-stage and bench member needs a unique representative gift. Save settings.</p></li></ol><p><a href=\"#gifts\">Need help choosing gifts? Open the gift mapping guide →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-settings-top.png\" data-caption=\"Multi PK settings 1 of 2: timer, stage count, members and bench\" aria-label=\"Multi PK settings 1 of 2: timer, stage count, members and bench\"><img src=\"assets/multi-settings-top.png\" alt=\"Multi PK settings 1 of 2: timer, stage count, members and bench\" loading=\"lazy\"></button><figcaption><span>Multi PK settings 1 of 2: timer, stage count, members and bench</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-settings.png\" data-caption=\"Multi PK settings 2 of 2: all gift mappings and Save Settings\" aria-label=\"Enlarge: Multi PK settings\"><img src=\"assets/multi-settings.png\" alt=\"Multi PK settings 2 of 2: all gift mappings and Save Settings\" loading=\"lazy\"></button><figcaption><span>Multi PK settings 2 of 2: all gift mappings and Save Settings</span><span></span></figcaption></figure><p><strong>Round Timer / On-stage Count</strong> — Set seconds and the number of members on stage (2–21).</p><p><strong>On Stage</strong> — Select exactly the number specified by On-stage Count.</p><p><strong>Bench Queue</strong> — Select waiting members. Their queue order determines who enters next.</p><p><strong>Gift Mapping</strong> — Every on-stage and waiting member needs a different representative gift.</p><h2>How to start</h2><p class=\"preflight\"><strong>Before starting: </strong>Check that On Stage matches On-stage Count, the bench order is correct and every member has a unique gift. Check the timer and OBS overlay.</p><p>Click ▶ Play, then Start round.</p><h2>How to end</h2><p>Let the timer finish, or click End round. Check the lowest score; if it is tied, select the departing member in Choose who leaves.</p><h2>How to continue</h2><p>After confirming who leaves, click Next round. The lowest-scoring member joins the bench queue end, the next waiting member enters, and everyone else stays. With no bench, there is no replacement. A tie for highest score does not add a single-player win streak.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-tie-controls-full.png\" data-caption=\"When the lowest score is tied, choose who leaves before continuing\" aria-label=\"Enlarge: When the lowest score is tied, choose who leaves before continuing\"><img src=\"assets/multi-tie-controls-full.png\" alt=\"When the lowest score is tied, choose who leaves before continuing\" loading=\"lazy\"></button><figcaption><span>When the lowest score is tied, choose who leaves before continuing</span><span></span></figcaption></figure>","zh":"<div class=\"hero\"><div class=\"eyebrow\">GAME MODE</div><h1>Multi PK · 多人轮换 PK</h1><p class=\"lead\">多人同台，分数最低者与候场队列轮换。</p></div><h2>适合什么场景</h2><p>适合多人同台、候场补位的轮换比赛。观众送各自代表礼物支持，每局结束后按最低分和候场队列换人。</p><h2>怎么设置</h2><ol class=\"steps\"><li><h3>设置上场与候场</h3><p>设置 On-stage count（2–21 人），On Stage 勾选人数必须与它一致，其余放入 Bench Queue。</p></li><li><h3>设置时长和礼物</h3><p>比赛时长 10–3600 秒。上场和候场成员都需要绑定各自唯一的代表礼物。保存设置。</p></li></ol><p><a href=\"#gifts\" style=\"color:var(--pink);font-size:13px\">不会选礼物？查看礼物绑定图解 →</a></p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-settings-top.png\" data-caption=\"Multi PK 设置 1/2：计时、上场人数、成员选择与替补\" aria-label=\"Multi PK 设置 1/2：计时、上场人数、成员选择与替补\"><img src=\"assets/multi-settings-top.png\" alt=\"Multi PK 设置 1/2：计时、上场人数、成员选择与替补\" loading=\"lazy\"></button><figcaption><span>Multi PK 设置 1/2：计时、上场人数、成员选择与替补</span><span></span></figcaption></figure><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-settings.png\" data-caption=\"Multi PK 设置 2/2：完整礼物绑定与 Save Settings\" aria-label=\"放大：Multi PK 设置界面\"><img src=\"assets/multi-settings.png\" alt=\"Multi PK 设置 2/2：完整礼物绑定与 Save Settings\" loading=\"lazy\"></button><figcaption><span>Multi PK 设置 2/2：完整礼物绑定与 Save Settings</span><span></span></figcaption></figure><p><strong>Round Timer / On-stage Count</strong> — 设置回合秒数及同时上场人数（2–21）。</p><p><strong>On Stage</strong> — 勾选上场成员，人数必须与 On-stage Count 一致。</p><p><strong>Bench Queue</strong> — 选择替补成员，队列顺序决定谁先补位。</p><p><strong>Gift Mapping</strong> — 上场成员与替补成员都要绑定各自不同的代表礼物。</p><h2>怎么开始</h2><p class=\"preflight\"><strong>开场前检查：</strong>确认上场人数与 On-stage Count 一致，候场顺序正确，所有成员礼物互不重复，并检查计时和 OBS 画面。</p><p>点击 ▶ Play 进入模式，再点击 Start round。</p><h2>怎么结束</h2><p>倒计时结束，或点击 End round，结束本局。先检查最低分；如最低分并列，在 Choose who leaves 中选择离场成员。</p><h2>怎么下一轮</h2><p>确认离场成员后点击 Next round。最低分成员回到候场队尾，下一位候场成员补位，其他成员留台；没有候场成员时不换人。最高分并列不增加单人连胜。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/multi-tie-controls-full.png\" data-caption=\"最低分并列时：先选择离场成员，再进入下一局\" aria-label=\"放大：最低分并列时：先选择离场成员，再进入下一局\"><img src=\"assets/multi-tie-controls-full.png\" alt=\"最低分并列时：先选择离场成员，再进入下一局\" loading=\"lazy\"></button><figcaption><span>最低分并列时：先选择离场成员，再进入下一局</span><span></span></figcaption></figure>"}},"scene":{"title":{"en":"Other scene tools","zh":"其他画面工具"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">SCENE AND TOOLS</div><h1>Other scene tools</h1><p class=\"lead\">Finish the basic setup first, then use these tools to suit your broadcast.</p></div><div class=\"details-wrap\"><details><summary>Ranking</summary><p>Open the gear next to Ranking, choose a list and enable its display. Available configurations include member totals, top gifters and likers. Goals can show gift-sender, like and new-follower targets.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/ranking-settings.png\" data-caption=\"Ranking: select game scores and Cast members to display\" aria-label=\"Ranking: select game scores and Cast members to display\"><img src=\"assets/ranking-settings.png\" alt=\"Ranking: select game scores and Cast members to display\" loading=\"lazy\"></button><figcaption><span>Ranking: select game scores and Cast members to display</span><span></span></figcaption></figure></details><details><summary>Lucky Wheel</summary><p>Enter one option per line in Options, set the result hold time from 1 to 15 seconds, and save. Click the play button beside Lucky Wheel to spin. The result does not automatically change game scores or members.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/wheel-settings.png\" data-caption=\"Lucky Wheel: one option per line and result hold time\" aria-label=\"Lucky Wheel: one option per line and result hold time\"><img src=\"assets/wheel-settings.png\" alt=\"Lucky Wheel: one option per line and result hold time\" loading=\"lazy\"></button><figcaption><span>Lucky Wheel: one option per line and result hold time</span><span></span></figcaption></figure></details><details><summary>Menu</summary><p>Menu displays gifts alongside custom names. Open the settings gear beside Menu in Scene.</p><p>Visibility shows or hides the menu. Layout selects vertical or horizontal order. Text opacity changes label transparency. Click the gift to replace it, enter a Name, use Add Item for more entries, or × to remove an entry. Drag the preview to move or resize the menu, then Save Settings.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/menu-settings.png\" data-caption=\"Menu: visibility, layout, custom names and gift selection\" aria-label=\"Menu: visibility, layout, custom names and gift selection\"><img src=\"assets/menu-settings.png\" alt=\"Menu: visibility, layout, custom names and gift selection\" loading=\"lazy\"></button><figcaption><span>Menu: visibility, layout, custom names and gift selection</span><span></span></figcaption></figure></details><details><summary>Gifter Binding</summary><p>Enable it from Modes settings if needed. It establishes viewer-to-member attribution and provides a fallback for later unmatched gifts. Check representative gift mappings first.</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gifter-binding-full.png\" data-caption=\"Modes Settings: Gifter Binding switch\" aria-label=\"Modes Settings: Gifter Binding switch\"><img src=\"assets/gifter-binding-full.png\" alt=\"Modes Settings: Gifter Binding switch\" loading=\"lazy\"></button><figcaption><span>Modes Settings: Gifter Binding switch</span><span></span></figcaption></figure></details></div>","zh":"<div class=\"hero\"><div class=\"eyebrow\">SCENE &amp; TOOLS</div><h1>其他画面工具</h1><p class=\"lead\">这些工具用于展示和互动。先完成基础开播流程，再按你的直播内容使用。</p></div><div class=\"details-wrap\"><details><summary>Ranking · 排行榜</summary><p>点击 Ranking 旁的齿轮，选择需要的榜单并显示。可按配置查看成员累计、送礼观众与点赞观众等榜单；Goals 可展示礼物人数、点赞和新增关注相关目标。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/ranking-settings.png\" data-caption=\"Ranking：选择统计的模式及需要展示的成员\" aria-label=\"Ranking：选择统计的模式及需要展示的成员\"><img src=\"assets/ranking-settings.png\" alt=\"Ranking：选择统计的模式及需要展示的成员\" loading=\"lazy\"></button><figcaption><span>Ranking：选择统计的模式及需要展示的成员</span><span></span></figcaption></figure></details><details><summary>Lucky Wheel · 幸运转盘</summary><p>打开转盘设置，在 Options 每行填写一个选项，设置结果停留时间（1–15 秒）并保存。点击 Lucky Wheel 旁的播放按钮转动。转盘结果不会自动替你修改游戏分数或切换成员。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/wheel-settings.png\" data-caption=\"Lucky Wheel：每行一个选项，设置结果停留时间\" aria-label=\"Lucky Wheel：每行一个选项，设置结果停留时间\"><img src=\"assets/wheel-settings.png\" alt=\"Lucky Wheel：每行一个选项，设置结果停留时间\" loading=\"lazy\"></button><figcaption><span>Lucky Wheel：每行一个选项，设置结果停留时间</span><span></span></figcaption></figure></details><details><summary>Menu · 菜单</summary><p>菜单用于展示礼物与自定义名称的对应关系。打开 Scene 中 Menu 旁的齿轮设置。</p><p>Visibility 控制菜单显示或隐藏；Layout 选择纵向或横向排列；Text opacity 调整文字透明度。点击礼物图标可更换礼物，Name 填展示名称，Add Item 添加条目，× 删除条目。拖动预览调整位置和大小，最后点击 Save Settings。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/menu-settings.png\" data-caption=\"Menu：显示开关、排列方向、自定义名称和礼物选择\" aria-label=\"Menu：显示开关、排列方向、自定义名称和礼物选择\"><img src=\"assets/menu-settings.png\" alt=\"Menu：显示开关、排列方向、自定义名称和礼物选择\" loading=\"lazy\"></button><figcaption><span>Menu：显示开关、排列方向、自定义名称和礼物选择</span><span></span></figcaption></figure></details><details><summary>Gifter Binding · 观众归属</summary><p>在 Modes 的设置入口中按需要启用。用于给观众建立成员归属，并对后续未匹配礼物进行归属兜底。使用前先确认代表礼物设置，避免归属理解错误。</p><figure class=\"shot\"><button class=\"zoom\" data-image=\"assets/gifter-binding-full.png\" data-caption=\"Modes Settings：Gifter Binding 观众归属开关\" aria-label=\"Modes Settings：Gifter Binding 观众归属开关\"><img src=\"assets/gifter-binding-full.png\" alt=\"Modes Settings：Gifter Binding 观众归属开关\" loading=\"lazy\"></button><figcaption><span>Modes Settings：Gifter Binding 观众归属开关</span><span></span></figcaption></figure></details></div>"}},"finish":{"title":{"en":"Finish and review records","zh":"结束与查看记录"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">WRAP UP</div><h1>Finish and review records</h1><p class=\"lead\">End the game, disconnect Studio and end the broadcast in your streaming software.</p></div><ol class=\"steps\"><li><h3>End the round and stop the mode</h3><p>In timed games, end the current round, then stop the mode.</p></li><li><h3>Click the top End button</h3><p>Disconnect Studio from the LIVE data feed.</p></li><li><h3>End the broadcast in your streaming software</h3><p>Disconnecting Studio does not close your TikTok LIVE. Confirm the broadcast has actually ended.</p></li></ol><h2>Review gifts and attribution</h2><p>Open the top record icon, <code>LIVE data and allocation audit</code>, to view the Current LIVE log or history.</p><details><summary>How do I assign an unallocated gift?</summary><p>Click Allocate on the unallocated entry, select the correct member, then use Allocate Full Gift. Check the entry first to avoid handling it twice.</p></details><details><summary>How do I correct the assigned member?</summary><p>Click the existing assigned name and use Move Full Gift to transfer the gift to the correct member. This moves existing score; do not add another copy.</p></details><details><summary>What format is the export?</summary><p>The current session export is JSON. It saves session data; it is not an Excel workbook or a backup of software settings.</p></details>","zh":"<div class=\"hero\"><div class=\"eyebrow\">WRAP UP</div><h1>结束与查看记录</h1><p class=\"lead\">游戏结束、Studio 断开和平台下播是三个操作，按顺序完成。</p></div><ol class=\"steps\"><li><h3>结束本局并停止玩法</h3><p>计时玩法先结束当前一局，再停止模式。</p></li><li><h3>点击 Studio 顶部 End</h3><p>断开 Studio 的直播数据连接。</p></li><li><h3>回到直播软件结束直播</h3><p>Studio 断开不会替你关闭平台直播间。确认直播软件已真正下播。</p></li></ol><h2>查看礼物与分配记录</h2><p>点击顶部记录图标 <code>LIVE data and allocation audit</code>，查看 Current LIVE 日志或历史记录。</p><div class=\"details-wrap\"><details><summary>礼物没有分到成员，怎么补？</summary><p>在未分配记录中点击 Allocate，选择正确成员，再用 Allocate Full Gift 分配整笔礼物。先核对这笔记录，避免重复处理。</p></details><details><summary>礼物分错成员，怎么改？</summary><p>点击已有归属成员的名字，使用 Move Full Gift 将原有礼物转移给正确成员。这是转移已有分数，不应另加一份。</p></details><details><summary>记录导出是什么格式？</summary><p>当前会话导出为 JSON。它用于保存会话数据，不是 Excel 表格，也不是软件配置备份。</p></details></div>"}},"help":{"title":{"en":"Troubleshooting","zh":"遇到问题"},"html":{"en":"<div class=\"hero\"><div class=\"eyebrow\">HELP</div><h1>Troubleshooting</h1><p class=\"lead\">Choose the symptom that matches what you see.</p></div><div class=\"details-wrap\"><details><summary>The camera preview is black</summary><p>Check that OBS Virtual Camera is running. Refresh Camera Settings and select the device again. For a physical camera, check availability and system permission.</p></details><details><summary>Studio shows video but OBS has no game content</summary><p>Check the OBS Overlay Runtime Browser source, the link copied from your current Studio, its position above the camera, and whether you clicked Play in the game mode.</p></details><details><summary>No LIVE data after Start</summary><p>Confirm the correct TikTok LIVE room is actually online. Check Studio’s connection status and network. Studio Start does not create a broadcast.</p></details><details><summary>A gift arrived but the score did not change</summary><p>Check whether the mode and round have started, the gift mapping and the active member. Then review the original gift and unallocated entries in the LIVE log.</p></details><details><summary>A Cast member is missing from the game</summary><p>Open that game’s settings, select the member and save. In Multi PK, also check On Stage and Bench Queue.</p></details><details><summary>I can’t edit Cast or switch accounts</summary><p>End the round and stop the mode before editing members. End the current Studio LIVE connection before switching accounts.</p></details><details><summary>Multi PK will not start the next round</summary><p>Check that the round has ended. If the lowest score is tied, use Choose who leaves first.</p></details><details><summary>Solo Stage did not rotate after a target</summary><p>Reaching a target does not rotate members. End the round, then click the next Start.</p></details></div><details><summary>Why does the game not appear in OBS after starting?</summary><p>If you have clicked Play / Start / Start round but the game overlay does not appear in OBS, select the Streamplay Browser Source in OBS Sources, open Properties, and click Refresh cache of current page. Then check the overlay again. Refresh the Browser Source, not the camera source.</p></details>","zh":"<div class=\"hero\"><div class=\"eyebrow\">HELP</div><h1>遇到问题</h1><p class=\"lead\">按你遇到的现象检查，一次解决一个问题。</p></div><div class=\"details-wrap\"><details><summary>中间预览黑屏或没有摄像头？</summary><p>先确认 OBS 已启动虚拟摄像头；到 Camera Settings 刷新来源并重新选择设备。若使用实体摄像头，检查设备是否可用、系统权限是否已允许。</p></details><details><summary>Studio 有画面，但 OBS 没有游戏内容？</summary><p>检查是否添加了 OBS Overlay Runtime 的浏览器源、链接是否来自当前 Studio、浏览器源是否放在摄像头上层，以及该玩法是否已点击 Play。</p></details><details><summary>点击顶部 Start 后没有直播数据？</summary><p>确认账号对应的 TikTok LIVE 已真实开播，再检查 Studio 的连接状态与网络。单独点击 Studio Start 不会创建直播间。</p></details><details><summary>收到礼物，成员分数没变？</summary><p>检查当前玩法和本局是否已开始、礼物是否绑定给正确成员、当前上场成员是谁，再到 LIVE 日志查看原始礼物与未分配记录。</p></details><details><summary>添加了 Cast，游戏里没有？</summary><p>Cast 总名单只是成员资料。进入当前玩法设置，勾选参赛成员并保存；Multi PK 还要检查 On Stage 和 Bench Queue。</p></details><details><summary>为什么不能改成员或切换账号？</summary><p>先结束当前比赛并停止模式。切换账号前还需要结束 Studio 当前 LIVE 连接，然后再操作。</p></details><details><summary>Multi PK 为什么不能开始下一局？</summary><p>先检查本局是否结束。如果最低分并列，需要先通过 Choose who leaves 选择一位离场成员。</p></details><details><summary>Solo Stage 达到目标，为什么没换人？</summary><p>达到目标不会自动换人。结束本轮后，点击下一次 Start 才轮换到下一位。</p></details></div><details><summary>点击开始后，OBS 为什么没有显示游戏画面？</summary><p>如果已点击 Play / Start / Start round，但 OBS 中没有显示互动叠加层，先在 OBS 的“来源”中选中 Streamplay 对应的浏览器源，打开“属性”，点击“刷新当前页面的缓存”（Refresh cache of current page），再检查画面。这里刷新的是浏览器源，不是摄像头源。</p></details>"}},"home":{"title":{"en":"Guide home","zh":"指南首页"},"html":{"zh":"<div class=\"hero guide-home-hero\"><div class=\"eyebrow\">STREAMPLAY STUDIO</div><h1>Streamplay 使用指南</h1><p class=\"lead\">从安装到第一场互动，按六步完成准备。</p></div><h2>首次使用路线</h2><ol class=\"home-route\"><li><a href=\"#download\"><span class=\"home-step\" aria-hidden=\"true\">↓</span><div><h3>下载安装</h3><p>选择适合电脑的安装包。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#account\"><span class=\"home-step\" aria-hidden=\"true\">↪</span><div><h3>登录账号</h3><p>确认当前使用的 Studio 账号。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#cast\"><span class=\"home-step\" aria-hidden=\"true\">+</span><div><h3>添加成员</h3><p>建立 Cast 名单。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#camera\"><span class=\"home-step\" aria-hidden=\"true\">▣</span><div><h3>接入画面</h3><p>连接摄像头与 OBS 互动叠加层。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#modes\"><span class=\"home-step\" aria-hidden=\"true\">▷</span><div><h3>选择玩法</h3><p>选一种模式，配置成员、时长和所需礼物。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#live\"><span class=\"home-step\" aria-hidden=\"true\">↗</span><div><h3>连接直播</h3><p>开播后连接 LIVE 数据，再开始游戏。</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li></ol><h2>常用入口</h2><div class=\"home-shortcuts\"><a href=\"#modes\"><h3>五种玩法 →</h3><p>设置、开始、结束与下一轮。</p></a><a href=\"#help\"><h3>遇到问题 →</h3><p>按现象查找处理方法。</p></a></div>","en":"<div class=\"hero guide-home-hero\"><div class=\"eyebrow\">STREAMPLAY STUDIO</div><h1>Streamplay User Guide</h1><p class=\"lead\">Six steps from installation to your first interactive session.</p></div><h2>First-session checklist</h2><ol class=\"home-route\"><li><a href=\"#download\"><span class=\"home-step\" aria-hidden=\"true\">↓</span><div><h3>Download and install</h3><p>Choose the installer for your computer.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#account\"><span class=\"home-step\" aria-hidden=\"true\">↪</span><div><h3>Sign in</h3><p>Check the active Studio account.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#cast\"><span class=\"home-step\" aria-hidden=\"true\">+</span><div><h3>Add members</h3><p>Create your Cast roster.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#camera\"><span class=\"home-step\" aria-hidden=\"true\">▣</span><div><h3>Connect video</h3><p>Set up your camera and OBS game overlay.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#modes\"><span class=\"home-step\" aria-hidden=\"true\">▷</span><div><h3>Choose a game</h3><p>Configure members, time and gifts where needed.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li><li><a href=\"#live\"><span class=\"home-step\" aria-hidden=\"true\">↗</span><div><h3>Connect LIVE</h3><p>Go live, connect LIVE data, then start the game.</p></div><span class=\"home-arrow\" aria-hidden=\"true\">→</span></a></li></ol><h2>Quick links</h2><div class=\"home-shortcuts\"><a href=\"#modes\"><h3>Game modes →</h3><p>Setup, start, end and next round.</p></a><a href=\"#help\"><h3>Troubleshooting →</h3><p>Find help by symptom.</p></a></div>"}}}};
